const D = { energy: .55, scale: 1, density: .55, speed: 1, flood: .55, mist: .5, hue: 96, x: .38, y: .26, style: 'monsoon', act: 'overcast', seed: 0, alpha: 1 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const ho = P.hue - 96;
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const sh = c => [hw(c[0] + ho), c[1], c[2]];

// ---------------- styles: five different theories of what a terrace IS ----------------
const STY = {
  // overcast silver light — the paddies are the only bright thing in the frame
  monsoon:  { skyT:[204,20,50], skyL:[196,10,72], wat:[198,10,80], crop:[104,26,32], bund:[92,22,17],
              far:[200,14,54], mist:[198,8,84], ramp:0, idx:0, grain:24 },
  // low sun — water goes molten, the crop drops to olive silhouette
  goldhour: { skyT:[26,44,54], skyL:[38,52,86], wat:[40,58,92], crop:[74,34,22], bund:[30,34,14],
              far:[28,26,50], mist:[36,22,76], ramp:0, idx:0, grain:30 },
  // moon path across black mirrors — dark key, near-monochrome, legible not empty
  nightpaddy:{ skyT:[232,50,16], skyL:[214,22,40], wat:[206,14,58], crop:[194,26,15], bund:[210,30,9],
              far:[218,26,26], mist:[204,12,52], ramp:0, idx:0, grain:16 },
  // ABSTRACTED: hypsometric survey sheet — elevation ramp + index contours, no water, no crop
  hypso:    { skyT:[212,58,14], skyL:[210,48,20], wat:[186,44,86], crop:[186,40,60], bund:[188,30,96],
              far:[210,44,22], mist:[196,30,34], ramp:1, idx:1, grain:6 },
  // ABSTRACTED: multispectral false colour — vegetation burns magenta, water goes navy void
  ndvi:     { skyT:[248,44,12], skyL:[250,34,20], wat:[244,72,26], crop:[332,72,64], bund:[300,40,32],
              far:[250,40,18], mist:[262,26,32], ramp:0, idx:0, grain:12 }
};
const st = STY[P.style] || STY.monsoon;

const en = Math.max(0, Math.min(1, P.energy));
const mi = Math.max(0, Math.min(1, P.mist));
const yt = height * P.y;                 // ridge line
const yb = height * 1.10;                // hill foot, below the frame
const span = yb - yt;
const key = width + 'x' + height + '|' + P.style + '|' + P.seed + '|' + Math.round(P.hue) + '|' + P.scale.toFixed(2) + '|' + P.density.toFixed(2) + '|' + P.flood.toFixed(2) + '|' + P.y.toFixed(3) + '|' + P.x.toFixed(3);

// elevation field: g(y) is monotonic and invertible, s(x)*m(y) carves spurs and gullies
const gEl = yy => Math.pow(Math.max(0, (yb - yy) / span), 1.6);
const gInv = v => yb - span * Math.pow(Math.max(0, Math.min(1.3, v)), 1 / 1.6);
const sX = xx => {
  const n = xx / Math.max(1, width);
  return Math.sin(n * 6.1 + fr(1) * 6.3) * .54 + Math.sin(n * 13.7 + fr(2) * 6.3) * .30
       + Math.sin(n * 24.3 + fr(3) * 6.3) * .16 + Math.sin(n * 3.1 + fr(4) * 6.3) * .40;
};
const mY = yy => (.030 + .105 * (1 - gEl(yy))) * (.5 + P.scale * .8);
// solve E(x,y) = c for y by fixed-point iteration — 4 passes is plenty, m varies slowly
const solve = (xx, c) => { let yy = gInv(c); const s = sX(xx); for (let i = 0; i < 4; i++) yy = gInv(c - s * mY(yy)); return yy; };

if (!S.sky || S.key !== key) {
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  const mk = (w, h) => { const g = createGraphics(Math.max(2, Math.ceil(w)), Math.max(2, Math.ceil(h))); g.colorMode(g.HSB, 360, 100, 100, 100); return g; };
  if (S.sky) { S.sky.remove(); S.hill.remove(); S.mist0.remove(); S.mist1.remove(); }
  S.sky = mk(W, H); S.hill = mk(W, H); S.mist0 = mk(W, Math.max(2, yt + u * .3)); S.mist1 = mk(W, Math.max(2, yt + u * .3));

  // --- sky ---
  const g = S.sky; g.noStroke();
  const cT = sh(st.skyT), cL = sh(st.skyL);
  for (let yy = 0; yy < H; yy++) { const c = L3(cT, cL, Math.pow(Math.min(1, yy / Math.max(1, yt + u * .12)), .9)); g.fill(c[0], c[1], c[2]); g.rect(0, yy, W, 1); }

  // --- far ridges behind the hill (aerial perspective, drifted live) ---
  const q = S.hill; q.noStroke();
  const farC = sh(st.far);
  for (let L = 0; L < 2; L++) {
    const c = L3(farC, sh(st.mist), .5 - L * .26);
    q.fill(c[0], c[1], c[2], 92);
    q.beginShape(); q.vertex(-20, H);
    for (let xx = -20; xx <= W + 20; xx += 22) {
      const n = Math.sin(xx * .0043 + L * 2.7 + fr(L + 11) * 6) * .6 + Math.sin(xx * .011 + L) * .3 + Math.sin(xx * .0017 + L * 4) * .8;
      q.vertex(xx, yt - u * (.015 + L * .045) - n * u * (.03 + L * .02));
    }
    q.vertex(W + 20, H); q.endShape(q.CLOSE);
  }

  // --- the terraces: filled bands between two solved contours + a bund lip on each ---
  const N = Math.max(6, Math.round((18 + P.density * 34) / Math.max(.5, P.scale)));
  const watC = sh(st.wat), cropC = sh(st.crop), bundC = sh(st.bund), mistC = sh(st.mist);
  const step = Math.max(8, width / 56);
  S.wpts = [];
  const isWater = k => st.ramp ? false : fr(k * 37 + 7) < P.flood;
  for (let k = 0; k < N; k++) {
    const c0 = k / N, c1 = (k + 1) / N;
    const near = 1 - k / N;                        // k=0 is the foot (nearest), k=N-1 the ridge
    const haze = Math.pow(1 - near, 1.5) * (.25 + .55 * mi);
    const wet = isWater(k);
    let col;
    if (st.ramp) col = L3(sh([st.crop[0], st.crop[1], st.crop[2]]), sh([st.wat[0], st.wat[1], st.wat[2]]), k / N);
    else col = wet ? watC.slice() : cropC.slice();
    // per-band variation so no two terraces are the same flat fill
    const jit = (fr(k * 13 + 5) - .5) * (wet ? 10 : 16);
    col = L3([col[0], col[1], Math.max(2, col[2] + jit)], mistC, haze);
    q.fill(col[0], col[1] * (1 - haze * .5), col[2], 100);
    q.beginShape();
    for (let xx = -step; xx <= W + step; xx += step) q.vertex(xx, solve(xx, c1));
    for (let xx = W + step; xx >= -step; xx -= step) q.vertex(xx, solve(xx, c0));
    q.endShape(q.CLOSE);

    // crop texture: hatched rows following the contour — texture over flat fill
    if (!wet && !st.ramp && near > .12) {
      const rows = Math.max(1, Math.floor(3 * near));
      q.strokeWeight(Math.max(.5, u * .0012 * near));
      for (let r = 0; r < rows; r++) {
        q.stroke(col[0], Math.min(99, col[1] + 14), Math.max(2, col[2] - 9 + r * 4), 40);
        q.noFill(); q.beginShape();
        for (let xx = -step; xx <= W + step; xx += step) q.vertex(xx + (fr(k + r) - .5) * 3, solve(xx, c0 + (c1 - c0) * (r + .8) / (rows + 1)));
        q.endShape();
      }
      q.noStroke();
    }
    // the bund: the earth lip holding the water in. Index contours get a heavier line.
    const heavy = st.idx && (k % 5 === 0);
    q.noFill();
    q.strokeWeight(Math.max(.6, u * (heavy ? .0022 : .0013) * (.35 + near * 1.5)));
    const bc = L3(bundC, mistC, haze);
    q.stroke(bc[0], bc[1], st.ramp ? Math.min(99, bc[2] + (heavy ? 10 : -18)) : bc[2], (st.ramp ? 55 : 70) * (.4 + near * .7));
    q.beginShape();
    for (let xx = -step; xx <= W + step; xx += step) q.vertex(xx, solve(xx, c0));
    q.endShape();
    q.noStroke();

    // sample specular anchors on the flooded bands for the live shimmer pass
    if (wet && S.wpts.length < 150) {
      const ns = Math.max(1, Math.floor(2 + near * 5));
      for (let i2 = 0; i2 < ns; i2++) {
        const xx = W * ((i2 + .5) / ns + (fr(k * 7 + i2) - .5) * .3);
        const ya = solve(xx, c0), yc = solve(xx, c1);
        S.wpts.push({ x: xx, y: (ya + yc) * .5, th: Math.abs(ya - yc), n: near, h: haze });
      }
    }
  }

  // --- valley mist: tileable so the linear scroll can never seam ---
  const mC = sh(st.mist);
  for (const [gg, n, yc, spr, thk, alp] of [[S.mist0, 9, yt + u * .05, u * .22, u * .05, 16], [S.mist1, 6, yt - u * .02, u * .12, u * .03, 20]]) {
    gg.noStroke();
    for (let i = 0; i < n; i++) {
      const bx = fr(i * 5 + 71) * W, by = yc + (fr(i * 5 + 72) - .5) * spr;
      const bw = u * (.24 + fr(i * 5 + 73) * .7), bhh = thk * (.5 + fr(i * 5 + 74));
      for (let rep = -1; rep <= 1; rep++) for (let kk = 0; kk < 4; kk++) {
        gg.fill(mC[0], mC[1] * (1 - kk * .1), Math.min(99, mC[2] + kk * 2), alp * (1 - kk * .2));
        gg.ellipse(bx + rep * W, by + kk * bhh * .14, bw * (1 - kk * .12), bhh * (1 - kk * .08));
      }
    }
  }
  S.key = key;
}

// ---------------- act: the light over minutes ----------------
const sec = ((Math.floor(K.section) % 8) + 8) % 8;
const ACT = { overcast: { lum: .9 + sec * .012, mist: 1 }, clearing: { lum: .8 + sec * .04, mist: 1.3 - sec * .13 }, squall: { lum: 1.05 - sec * .045, mist: .7 + sec * .1 } };
const act = ACT[P.act] || ACT.overcast;
const mistAmt = Math.max(0, Math.min(1.5, act.mist));

noStroke();
image(S.sky, 0, 0);
const W2 = S.mist0.width;
const scr = (g, px, yy, a) => { const ox = ((px % W2) + W2) % W2; if (a < 100) tint(0, 0, 100, a); image(g, ox - W2, yy); image(g, ox, yy); if (a < 100) noTint(); };
scr(S.mist0, -K.t * u * .0095 * P.speed, 0, 100 * Math.min(1, mistAmt));

// hill drifts a touch on two incommensurate rates — a slow hand-held camera, not a slide
const hdx = (Math.sin(K.t * .019) * .7 + Math.sin(K.t * .0431 + 1.2) * .3) * u * .004 * P.speed;
const hdy = Math.sin(K.t * .0233 + 2.1) * u * .0018;
image(S.hill, hdx, hdy);

// ---------------- live shimmer on the flooded bands ----------------
const watC2 = sh(st.wat);
const lightX = width * P.x + Math.sin(K.t * .0117) * width * .10;
if (S.wpts && !st.ramp) {
  blendMode(P.style === 'nightpaddy' ? ADD : BLEND);
  for (let i = 0; i < S.wpts.length; i++) {
    const w = S.wpts[i];
    // three incommensurate real-time terms: never byte-identical 8 s later
    const sm = .5 + .5 * (Math.sin(K.t * (.61 + i * .009) + i) * .55 + Math.sin(K.t * 1.43 + i * 2.1) * .30 + Math.sin(K.t * 2.29 + i * .7) * .15);
    // the specular falls off away from where the light is standing
    const fall = Math.max(0, 1 - Math.abs(w.x + hdx - lightX) / (width * .62));
    const gain = (.35 + .65 * en) * (.4 + .6 * sm) * (.3 + .7 * fall) + A.treble * .22;
    const c = L3(watC2, sh(st.mist), w.h);
    fill(c[0], c[1] * .7, Math.min(99, c[2] + 12 + 16 * gain), (18 + 46 * gain) * (1 - w.h * .6));
    ellipse(w.x + hdx + Math.sin(K.t * .21 + i) * u * .004, w.y + hdy, Math.max(2, w.th * (.5 + 1.6 * sm)), Math.max(1.2, w.th * .5));
  }
  blendMode(BLEND);
}

// near mist bank, in FRONT of the hill — this is what sells the third dimension
scr(S.mist1, -K.t * u * .0215 * P.speed - u * .35, u * .02, 100 * Math.min(1, mistAmt * .85));

// ---------------- a broad light sweep, the slowest thing in the frame ----------------
if (!st.ramp) {
  blendMode(ADD);
  const swg = (.25 + .75 * en) * act.lum * (.75 + .25 * K.swell) + A.lowmid * .2;
  for (let i = 3; i >= 0; i--) {
    fill(sh(st.skyL)[0], st.skyL[1] * .5, st.skyL[2], (3 + 5 * swg) * (1 - i * .16));
    ellipse(lightX, yt + u * (.02 + i * .05), u * (.5 + i * .55), u * (.22 + i * .3));
  }
  blendMode(BLEND);
}

// ---------------- grain, then the plate edge ----------------
if (st.grain > 8) {
  const ng = Math.floor(st.grain * 6);
  for (let i = 0; i < ng; i++) {
    const gx = ((fr(i * 3 + 601) * width) + Math.sin(K.t * .013 + i) * u * .003 + width) % width;
    const gy = fr(i * 3 + 602) * height;
    fill(hw(st.bund[0] + ho), st.bund[1] * .5, fr(i * 3 + 603) > .5 ? 94 : 5, 3 + fr(i) * 6);
    rect(gx, gy, u * .0016, u * .0016);
  }
}
for (let i = 0; i < 5; i++) {
  noFill(); strokeWeight(u * .055);
  stroke(hw(st.bund[0] + ho), st.bund[1], st.ramp ? st.skyT[2] : 7, 20 * (1 - i * .17));
  rect(-u * .03 + i * u * .03, -u * .03 + i * u * .03, width + u * .06 - i * u * .06, height + u * .06 - i * u * .06);
}
noStroke();

if (P.alpha < 1) { fill(hw(st.bund[0] + ho), st.bund[1] * .5, 5, (1 - P.alpha) * 100); rect(0, 0, width, height); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
